1	/* branch_mispred — W1.5a branch-misprediction-dense probe kernel.
2	 *
3	 * Purpose (docs/gem5-fi/ooo/03-workloads.md, branch_mispred_dense):
4	 *   construct a large number of data-dependent, unpredictable conditional
5	 *   branches (conditional-branch traversal over a randomly permuted array),
6	 *   deliberately driving the branch misprediction rate up so RAT/Rename
7	 *   checkpoints are frequently triggered and then recovered (branch
8	 *   mispredict squashes).  Self-check = accumulated checksum plus
9	 *   permutation statistics (result-array self-verification), printed as one
10	 *   FINAL=<16hex> line (tools/classify.py _CHECKSUM_RE; the no-injection
11	 *   value is the golden, native == gem5).
12	 *
13	 * Structure:
14	 *   1. Fixed-seed LCG (same Knuth 64-bit generator family as smoke.c) fills
15	 *      perm[0..4095] = 0..4095, then one full Fisher-Yates shuffle.
16	 *   2. BP_ROUNDS traversals.  Each round first re-shuffles a rotating
17	 *      512-entry window with the continuing LCG stream (per spec: seed
18	 *      shuffle over multiple rounds), so branch-outcome streams never
19	 *      repeat across rounds and no predictor can lock onto them; then it
20	 *      traverses the whole array doing five data-dependent conditional
21	 *      branches per element:
22	 *        B1 parity        if (v & 1)                — 50/50 random
23	 *        B2 threshold     if (v > thr)              — thr evolves from
24	 *                                                      branch outcomes
25	 *        B3 state parity  if ((v ^ st) & 0x10)      — mixes live state
26	 *        B4 mix parity    if ((v ^ (v >> 3)) & 4)
27	 *        B5 state parity  if (((v >> 1) ^ st) & 0x20)
28	 *      Every arm writes a *distinct* live global slot (sc[k], read back
29	 *      into the checksum) plus an accumulator update.  ARM64 has no
30	 *      predicated stores, so arms with stores cannot be if-converted to
31	 *      csel — these stay REAL conditional branches (verified post-build by
32	 *      objdump: conditional-branch vs csel count in the hot loop).
33	 *   3. Verification pass: permutation statistics (circular descents, fixed
34	 *      points, displacement xor-sum, O(K^2) inversion count over a fixed
35	 *      256-slice) plus all accumulators fold into the FINAL checksum.
36	 *
37	 * Determinism: unsigned integer arithmetic only — no FP, no UB, no
38	 * environment dependence — so the native host run and gem5 SE produce a
39	 * byte-identical FINAL line.
40	 *
41	 * Size: ~ten million dynamic instructions — gem5 C3 SE in tens of seconds
42	 * (measured hostSeconds recorded in README.md), within the 60s W1 SE
43	 * budget; density gate mispredicts/commits >= 5% (reg_chain baseline
44	 * ~0.001%).
45	 */
46	#include <unistd.h>
47	#include <stdint.h>
48	#include <string.h>
49	
50	#define BP_N       4096u  /* permutation size (spec: 4096 items) */
51	#define BP_ROUNDS  48u    /* traversals (sized for C3 SE <= 60s) */
52	#define BP_WIN     512u   /* per-round re-shuffle window (rotating) */
53	#define BP_SLICE   256u   /* inversion-count slice (O(K^2) statistic) */
54	
55	static uint32_t perm[BP_N];
56	static uint32_t sc[10];   /* live per-arm store targets (block csel) */
57	
58	static uint64_t rng_state = 0x853c49e6748fea9bULL; /* fixed seed */
59	
60	static uint32_t rnd(void)
61	{
62	    rng_state = rng_state * 6364136223846793005ULL
63	              + 1442695040888963407ULL;
64	    return (uint32_t)(rng_state >> 33);
65	}
66	
67	/* Fisher-Yates inside perm[base .. base+len): the whole array stays a
68	 * permutation of 0..N-1, so the end-of-run permutation statistics remain
69	 * well-defined. */
70	static void shuffle_window(uint32_t base, uint32_t len)
71	{
72	    for (uint32_t k = len - 1; k > 0; --k) {
73	        uint32_t j = rnd() % (k + 1);
74	        uint32_t a = perm[base + k];
75	        uint32_t b = perm[base + j];
76	        perm[base + k] = b;
77	        perm[base + j] = a;
78	    }
79	}
80	
81	static void put(const char *s){ write(1, s, strlen(s)); }
82	
83	static void put_hex64(uint64_t v){
84	    char out[16];
85	    for (int i = 15; i >= 0; --i){
86	        unsigned d = v & 0xf;
87	        out[i] = d < 10 ? '0' + d : 'a' + d - 10;
88	        v >>= 4;
89	    }
90	    write(1, out, sizeof(out));
91	}
92	
93	/* deterministic 64-bit fold (hash_combine + splitmix-style finalizer) */
94	static uint64_t fold(uint64_t h, uint64_t v)
95	{
96	    h ^= v + 0x9e3779b97f4a7c15ULL + (h << 6) + (h >> 2);
97	    h ^= h >> 29;
98	    h *= 0xbf58476d1ce4e5b9ULL;
99	    h ^= h >> 32;
100	    return h;
101	}
102	
103	int main(void)
104	{
105	    uint64_t acc1 = 0, acc2 = 0, acc3 = 0, acc4 = 0;
106	    uint32_t st  = 0x1234567u;   /* live state, feeds B3/B4/B5 conditions */
107	    uint32_t thr = 2048u;        /* outcome-evolving threshold (B2) */
108	
109	    /* 1. random permutation, fixed seed */
110	    for (uint32_t i = 0; i < BP_N; ++i)
111	        perm[i] = i;
112	    shuffle_window(0, BP_N);
113	
114	    /* 2. traversals: data-dependent conditional branches over perm[] */
115	    for (uint32_t r = 0; r < BP_ROUNDS; ++r) {
116	        shuffle_window((r % (BP_N / BP_WIN)) * BP_WIN, BP_WIN);
117	
118	        for (uint32_t i = 0; i < BP_N; ++i) {
119	            uint32_t v = perm[i];
120	
121	            /* B1: parity of a permutation element — 50/50 random */
122	            if (v & 1u) {
123	                acc1 += v;
124	                sc[0] = v;
125	            } else {
126	                acc1 ^= (uint64_t)(v >> 1);
127	                sc[1] = v >> 2;
128	            }
129	
130	            /* B2: threshold against an outcome-evolving threshold */
131	            if (v > thr) {
132	                acc2 += (uint64_t)v * 3u;
133	                thr = thr + 1u + (v & 7u);
134	                sc[2] = v;
135	            } else {
136	                acc2 ^= (uint64_t)(v >> 2);
137	                thr = thr - 1u - (v & 3u);
138	                sc[3] = v >> 3;
139	            }
140	
141	            /* B3: parity mixed with live state */
142	            if ((v ^ st) & 0x10u) {
143	                acc3 += (uint64_t)v * st;
144	                sc[4] = v;
145	            } else {
146	                acc3 ^= (uint64_t)(v + st);
147	                sc[5] = v >> 4;
148	            }
149	
150	            /* B4: bit-mix parity of the element */
151	            if ((v ^ (v >> 3)) & 4u) {
152	                acc4 += v + (v << 8);
153	                sc[6] = v;
154	            } else {
155	                acc4 -= v ^ (st >> 3);
156	                sc[7] = v >> 5;
157	            }
158	
159	            /* B5: shifted parity mixed with live state */
160	            if (((v >> 1) ^ st) & 0x20u) {
161	                acc1 += (uint64_t)v * 5u;
162	                sc[8] = v;
163	            } else {
164	                acc3 -= (uint64_t)(v ^ st);
165	                sc[9] = v >> 6;
166	            }
167	
168	            /* unconditional state update (keeps B3/B4/B5 conditions
169	             * data-dependent on the fresh element stream) */
170	            st = st * 3u + (v & 3u);
171	        }
172	    }
173	
174	    /* 3. permutation statistics — the self-check surface (spec: 排列的统计量) */
175	    uint64_t descents = 0, fixedpts = 0, dispx = 0, inversions = 0;
176	    for (uint32_t i = 0; i < BP_N; ++i) {
177	        if (perm[i] > perm[(i + 1u) & (BP_N - 1u)])
178	            ++descents;                    /* circular descent count */
179	        if (perm[i] == i)
180	            ++fixedpts;                    /* fixed points */
181	        dispx += (perm[i] ^ i) & 0xffu;    /* displacement xor-sum */
182	    }
183	    for (uint32_t i = 0; i < BP_SLICE; ++i)
184	        for (uint32_t j = i + 1u; j < BP_SLICE; ++j)
185	            if (perm[i] > perm[j])
186	                ++inversions;              /* slice inversion count */
187	
188	    /* fold everything into the FINAL checksum */
189	    uint64_t final = 0x0123456789abcdefULL;
190	    final = fold(final, acc1);
191	    final = fold(final, acc2);
192	    final = fold(final, acc3);
193	    final = fold(final, acc4);
194	    final = fold(final, (uint64_t)st);
195	    final = fold(final, (uint64_t)thr);
196	    final = fold(final, descents);
197	    final = fold(final, fixedpts);
198	    final = fold(final, dispx);
199	    final = fold(final, inversions);
200	    for (uint32_t k = 0; k < 10; ++k)
201	        final = fold(final, (uint64_t)sc[k]);
202	
203	    put("FINAL=");
204	    put_hex64(final);
205	    put("\n");
206	    return 0;
207	}
